const MAX = 12;
const input = $input.first().json;

// Try several possible body shapes (n8n webhook versions / proxies wrap differently)
const candidates = [];
if (input && typeof input === 'object') {
  if (input.body && typeof input.body === 'object') candidates.push(input.body);
  candidates.push(input);
  if (input.json && typeof input.json === 'object') candidates.push(input.json);
}
const body = candidates.find(b => b && (typeof b.your_url !== 'undefined' || typeof b.keyword !== 'undefined')) || candidates[0] || {};

function shapeReport() {
  const topKeys = Object.keys(input || {});
  const bodyKeys = Object.keys(body || {});
  return ' (top-level keys: [' + topKeys.join(', ') + '], chosen-body keys: [' + bodyKeys.join(', ') + '])';
}

function cleanUrl(raw) {
  // Strip control chars + zero-width / BOM chars that sneak in from clipboard paste
  return String(raw == null ? '' : raw).replace(/[\u0000-\u001F\u007F\u200B-\u200D\uFEFF]/g, '').trim();
}

function coerceUrl(raw, label) {
  const v = cleanUrl(raw);
  if (!v) throw new Error(label + ' is required.' + shapeReport());
  const candidate = /^https?:\/\//i.test(v) ? v : 'https://' + v;
  // Permissive http(s) + host check. Avoids n8n sandbox quirks with the URL constructor.
  if (!/^https?:\/\/[^\s\/]+/i.test(candidate)) {
    throw new Error(label + ' is not a valid URL (received: ' + JSON.stringify(v) + ')');
  }
  return candidate;
}

const keyword = String(body.keyword || '').trim();
if (!keyword) throw new Error('keyword is required.' + shapeReport());

// your_url is now optional — if provided, validate; if empty, skip
const your_url = body.your_url ? coerceUrl(body.your_url, 'your_url') : '';

let urls = Array.isArray(body.urls) ? body.urls.map(cleanUrl).filter(Boolean) : [];
urls = urls.map(u => /^https?:\/\//i.test(u) ? u : 'https://' + u);
urls = [...new Set(urls)].slice(0, MAX);
if (!urls.length) throw new Error('at least 1 competitor URL is required.' + shapeReport());

return [{
  json: {
    keyword,
    your_url,
    urls,
    location: String(body.location || 'United States').trim(),
    language: String(body.language || 'en').trim(),
    paa: Array.isArray(body.paa) ? body.paa.map(String).slice(0, 8) : [],
    related_searches: Array.isArray(body.related_searches) ? body.related_searches.map(String).slice(0, 10) : [],
    requested_at: body.requested_at || new Date().toISOString()
  }
}];

const inputs = $input.first().json;
const all = inputs.your_url ? [inputs.your_url, ...inputs.urls] : [...inputs.urls];
return all.map(u => ({ json: { url: u, is_yours: inputs.your_url ? u === inputs.your_url : false } }));

// Extract on-page signals from the Firecrawl response for one URL.
// Mirrors webhook-service/handlers/serp-analysis.js extractSignals().
// Runs once per input item (mode: runOnceForEachItem) so each scraped page
// gets its own extraction.

const meta = $('Build URL List').item.json;
const url = meta.url;
const is_yours = !!meta.is_yours;
const resp = $input.item.json || {};

function getDomain(u) {
  const m = /^https?:\/\/([^\/?#]+)/i.exec(String(u || ''));
  return m ? m[1].replace(/^www\./i, '').toLowerCase() : '';
}
function decodeEntities(s) {
  return String(s || '')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'");
}
function stripMarkdown(md) {
  return String(md || '')
    .replace(/```[\s\S]*?```/g, ' ')
    .replace(/`[^`]*`/g, ' ')
    .replace(/!\[[^\]]*]\([^)]*\)/g, ' ')
    .replace(/\[([^\]]+)]\([^)]*\)/g, '$1')
    .replace(/^\s{0,3}#{1,6}\s+/gm, '')
    .replace(/^[*+-]\s+/gm, '')
    .replace(/^\d+\.\s+/gm, '')
    .replace(/[*_~>]/g, ' ')
    .replace(/\|/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function parseHeadingsFromMarkdown(md) {
  const out = []; const re = /^(\s{0,3})(#{1,6})\s+(.+?)\s*#*\s*$/gm; let m;
  while ((m = re.exec(String(md || ''))) !== null) {
    const level = m[2].length;
    const text = m[3].replace(/[`*_~]/g, '').trim();
    if (text) out.push({ level, text });
  }
  return out;
}
function parseHeadingsFromHtml(html) {
  const out = []; const re = /<h([1-6])\b[^>]*>([\s\S]*?)<\/h\1>/gi; let m;
  while ((m = re.exec(String(html || ''))) !== null) {
    const text = decodeEntities(m[2].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim());
    if (text) out.push({ level: Number(m[1]), text });
  }
  return out;
}
function extractTagText(html, tag) {
  const re = new RegExp('<' + tag + '\\b[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'i');
  const m = re.exec(String(html || ''));
  return m ? decodeEntities(m[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()) : '';
}
function extractMetaDescription(html) {
  const re = /<meta\b[^>]*name=["']description["'][^>]*>/i;
  const tag = (re.exec(String(html || '')) || [])[0] || '';
  const c = /content=["']([^"']*)["']/i.exec(tag);
  return c ? decodeEntities(c[1]).trim() : '';
}
function extractSchemaTypes(html) {
  const out = new Set();
  const re = /"@type"\s*:\s*"([^"]+)"/g; let m;
  while ((m = re.exec(String(html || ''))) !== null) out.add(m[1]);
  const re2 = /itemtype=["']https?:\/\/schema\.org\/([^"']+)["']/g;
  while ((m = re2.exec(String(html || ''))) !== null) out.add(m[1]);
  return [...out];
}
function countMatches(s, re) { const m = String(s || '').match(re); return m ? m.length : 0; }

// Detect Firecrawl error → emit minimal record with error.
if (resp.success === false || resp.error) {
  return { json: {
    url, domain: getDomain(url), is_yours, source: 'fallback',
    error: resp.error || resp.message || 'firecrawl returned success=false',
    title: '', h1: '', meta_description: '', meta_description_length: 0,
    title_length: 0, word_count: 0, headings_outline: [],
    heading_counts: { h1: 0, h2: 0, h3: 0, h4: 0 },
    internal_links: 0, external_links: 0, image_count: 0, video_count: 0,
    table_count: 0, list_count: 0, code_block_count: 0, blockquote_count: 0,
    has_faq_section: false, schema_types: [], language: ''
  } };
}

const data = resp.data || {};
const md = String(data.markdown || '');
const html = String(data.html || '');
const pageMeta = data.metadata || {};
const links = Array.isArray(data.links) ? data.links : [];

const mdHeadings = parseHeadingsFromMarkdown(md);
const htmlHeadings = mdHeadings.length ? mdHeadings : parseHeadingsFromHtml(html);

const plain = stripMarkdown(md) || (html ? decodeEntities(html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, ' ').replace(/<style[^>]*>[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()) : '');
const wordCount = plain ? plain.split(/\s+/).filter(Boolean).length : 0;

const domain = getDomain(url);
let internalLinks = 0, externalLinks = 0;
for (const l of links) {
  const d = getDomain(l);
  if (!d) continue;
  if (d === domain) internalLinks += 1; else externalLinks += 1;
}

const headingTexts = htmlHeadings.map(h => h.text);
const hasFaqHeading = headingTexts.some(t => /faq|frequently asked|q&a/i.test(t)) || headingTexts.filter(t => /\?$/.test(t)).length >= 3;

const tablesMd = countMatches(md, /^\s*\|.*\|\s*$/gm);
const tablesHtml = countMatches(html, /<table\b/gi);
const tableCount = Math.max(tablesMd >= 2 ? Math.floor(tablesMd / 3) : 0, tablesHtml);
const imageCount = countMatches(md, /!\[[^\]]*]\([^)]*\)/g) + countMatches(html, /<img\b/gi);
const videoCount = countMatches(html, /<iframe\b[^>]*(youtube|vimeo|wistia|loom)/gi) + countMatches(html, /<video\b/gi);
const bullets = countMatches(md, /^[*+-]\s+/gm);
const numbered = countMatches(md, /^\d+\.\s+/gm);
const listCount = bullets + numbered;
const codeBlocks = countMatches(md, /```[\s\S]*?```/g);
const blockquotes = countMatches(md, /^>\s+/gm);
const schemaTypes = extractSchemaTypes(html);

const title = (pageMeta.title || pageMeta.ogTitle || extractTagText(html, 'title') || '').trim();
const metaDescription = (pageMeta.description || pageMeta.ogDescription || extractMetaDescription(html) || '').trim();
const h1 = htmlHeadings.find(h => h.level === 1);

return {
  json: {
    url, domain, is_yours, source: 'firecrawl', error: null,
    title,
    h1: h1 ? h1.text : '',
    meta_description: metaDescription,
    meta_description_length: metaDescription.length,
    title_length: title.length,
    word_count: wordCount,
    headings_outline: htmlHeadings.slice(0, 60),
    heading_counts: {
      h1: htmlHeadings.filter(h => h.level === 1).length,
      h2: htmlHeadings.filter(h => h.level === 2).length,
      h3: htmlHeadings.filter(h => h.level === 3).length,
      h4: htmlHeadings.filter(h => h.level === 4).length
    },
    internal_links: internalLinks,
    external_links: externalLinks,
    image_count: imageCount,
    video_count: videoCount,
    table_count: tableCount,
    list_count: listCount,
    code_block_count: codeBlocks,
    blockquote_count: blockquotes,
    has_faq_section: hasFaqHeading,
    schema_types: schemaTypes,
    language: pageMeta.language || pageMeta.ogLocale || ''
  }
};

// Collect per-URL signals back into a single item with your_page + competitors[] + aggregate.
const inputs = $('Normalize Input').first().json;
const allItems = $input.all().map(it => it.json);

const yourPage = allItems.find(p => p.is_yours) || null;
const competitors = yourPage ? allItems.filter(p => !p.is_yours) : allItems;

function median(arr) {
  const xs = arr.filter(n => Number.isFinite(n)).sort((a, b) => a - b);
  if (!xs.length) return null;
  const mid = Math.floor(xs.length / 2);
  return xs.length % 2 ? xs[mid] : Math.round((xs[mid - 1] + xs[mid]) / 2);
}

const ok = competitors.filter(c => !c.error);
const schemaFreq = {};
for (const c of ok) for (const t of c.schema_types || []) schemaFreq[t] = (schemaFreq[t] || 0) + 1;

const aggregate = ok.length ? {
  pages_analyzed: ok.length,
  pages_failed: competitors.length - ok.length,
  median_word_count: median(ok.map(c => c.word_count)),
  median_h2_count: median(ok.map(c => c.heading_counts.h2)),
  median_internal_links: median(ok.map(c => c.internal_links)),
  median_external_links: median(ok.map(c => c.external_links)),
  median_image_count: median(ok.map(c => c.image_count)),
  median_video_count: median(ok.map(c => c.video_count)),
  faq_section_share: Math.round((ok.filter(c => c.has_faq_section).length / ok.length) * 100),
  table_share: Math.round((ok.filter(c => c.table_count > 0).length / ok.length) * 100),
  schema_type_frequency: schemaFreq
} : {
  pages_analyzed: 0,
  pages_failed: competitors.length,
  median_word_count: null, median_h2_count: null,
  median_internal_links: null, median_external_links: null,
  median_image_count: null, median_video_count: null,
  faq_section_share: 0, table_share: 0, schema_type_frequency: {}
};

return [{
  json: {
    ...inputs,
    your_page: yourPage,
    competitors,
    aggregate
  }
}];

const upstream = $('Build LLM Payload').first().json;
const response = $input.first().json;

const your_page = upstream.your_page || {};
const aggregate = upstream.aggregate || {};
const hasYourPage = !!(upstream.your_url || your_page.url);

const skeleton = {
  summary: '',
  serp_archetype: '',
  common_patterns: [],
  your_strengths: hasYourPage ? [] : undefined,
  gaps: hasYourPage ? [] : undefined,
  standout_signals: [],
  recommendations: [],
  meta_comparison: hasYourPage ? {
    your_title: your_page.title || '',
    your_title_length: your_page.title_length || 0,
    suggested_title: '',
    title_needs_change: false,
    your_meta_description: your_page.meta_description || '',
    your_meta_description_length: your_page.meta_description_length || 0,
    suggested_meta_description: '',
    meta_needs_change: false
  } : undefined,
  content_depth_verdict: hasYourPage ? '' : undefined,
  target_word_count: aggregate.median_word_count
    ? Math.round(aggregate.median_word_count * 0.85) + '-' + Math.round(aggregate.median_word_count * 1.15) + ' words (anchored to competitor median)'
    : ''
};

let analysis = skeleton;
let ai_error = null;
let ai_debug = null;

if (response && response.error) {
  ai_error = 'OpenRouter error: ' + (response.error.message || response.error.code || JSON.stringify(response.error));
  ai_debug = { kind: 'error_field', error: response.error };
} else {
  const choice = response && response.choices && response.choices[0];
  // OpenRouter sometimes nests upstream provider errors at choices[0].error
  // (e.g. Gemini 2.5 Pro "Upstream idle timeout exceeded" when thinking takes too long).
  if (choice && choice.error) {
    const cerr = choice.error;
    ai_error = 'Upstream provider error: ' + (cerr.message || cerr.code || JSON.stringify(cerr));
    ai_debug = { kind: 'choice_error', error: cerr, finish_reason: choice.finish_reason, native_finish_reason: choice.native_finish_reason };
  } else {
  const text = choice && choice.message && choice.message.content;
  if (!text) {
    const finishReason = choice && choice.finish_reason;
    const usage = response && response.usage;
    ai_error = 'No content in OpenRouter response (finish_reason: ' + (finishReason || 'unknown') + ')';
    ai_debug = {
      kind: 'empty_content',
      response_keys: response ? Object.keys(response) : [],
      finish_reason: finishReason,
      usage,
      first_choice_keys: choice ? Object.keys(choice) : [],
      message_keys: (choice && choice.message) ? Object.keys(choice.message) : [],
      raw_response_preview: JSON.stringify(response || {}).slice(0, 3000)
    };
  } else {
    let parsed;
    try { parsed = JSON.parse(text); }
    catch (e) {
      const cleaned = text.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
      try { parsed = JSON.parse(cleaned); }
      catch (e2) {
        ai_error = 'Failed to parse JSON from model';
        analysis = { ...skeleton, raw_text: text };
        ai_debug = { kind: 'parse_fail', text_preview: text.slice(0, 1000) };
      }
    }
    if (parsed) analysis = { ...skeleton, ...parsed };
  }
  }
}

return [{
  json: {
    keyword: upstream.keyword,
    your_url: upstream.your_url || '',
    location: upstream.location,
    language: upstream.language,
    your_page: hasYourPage ? your_page : null,
    competitors: upstream.competitors,
    aggregate,
    ...analysis,
    ai_model: 'google/gemini-2.5-pro',
    generated_at: new Date().toISOString(),
    ...(ai_error ? { ai_error } : {}),
    ...(ai_debug ? { ai_debug } : {})
  }
}];
